// Contract logic tests for FungibleToken.
//
// These run the REAL contract (`FungibleTokenExample.runar.rs`, included below
// via `#[path]`), not a copy of it. They used to run an inline
// re-implementation typed out again in this file — one that had drifted to a
// four-argument `merge` the shipped contract no longer has — so deleting the
// merge covenant's prevouts assert from the shipped contract left
// `test_merge_tampered_prevouts_fails` green (F-057).
//
// `self.add_output(...)` is generated by `#[runar::contract]`; it records each
// output on a thread-local log that `FungibleToken::take_outputs()` drains.
// Each `#[test]` runs on its own thread, so the log starts empty in every test.
//
// Rejection tests name the assert they expect to fire (`should_panic(expected
// = ...)`). A bare `#[should_panic]` is satisfied by ANY later assert, so it
// stays green when the assert it is about is deleted.
//
// What these prove: the shipped `transfer` / `send` bodies produce the asserted
// outputs, and the shipped `merge` refuses a negative `other_balance` and a
// prevouts list that does not hash to the preimage's hashPrevouts, at those
// specific asserts. What they do not prove: an HONEST merge. Its W8 companion
// walk needs `hash256(other_parent_tx)` to equal the companion txid inside
// `all_prevouts`, and the native mocks pin `extract_hash_prevouts` to
// `hash256([0; 72])` and return an empty scriptCode, so no native input can
// reach the merge's `add_output`. `test_merge_honest_prevouts_reach_companion_binding`
// pins how far it gets; the honest merge itself is pinned on `@bsv/sdk` Spend
// in `packages/runar-testing/src/__tests__/w8-token-ft-solo-merge-known-broken.test.ts`.
// Nothing here says anything about the compiled Bitcoin Script.

#[path = "FungibleTokenExample.runar.rs"]
mod contract;

use contract::*;
use runar::prelude::*;

fn alice() -> PubKey { ALICE.pub_key.to_vec() }
fn bob() -> PubKey { BOB.pub_key.to_vec() }
fn alice_sig() -> Sig { ALICE.sign_test_message() }

fn token(owner: PubKey, balance: Bigint, merge_balance: Bigint) -> FungibleToken {
    FungibleToken {
        owner,
        balance,
        merge_balance,
        token_id: b"test-token-001".to_vec(),
        tx_preimage: vec![],
    }
}

fn new_token(owner: PubKey, balance: Bigint) -> FungibleToken {
    token(owner, balance, 0)
}

#[test]
fn test_transfer() {
    let mut c = new_token(alice(), 100);
    c.transfer(&alice_sig(), bob(), 30, 1000);
    // token_id is readonly: transfer must not touch it.
    assert_eq!(c.token_id, b"test-token-001".to_vec());
    let o = FungibleToken::take_outputs();
    assert_eq!(o.len(), 2);
    assert_eq!(o[0].owner, bob());
    assert_eq!(o[0].satoshis, 1000);
    assert_eq!(o[0].balance, 30);
    assert_eq!(o[0].merge_balance, 0);
    assert_eq!(o[1].owner, alice());
    assert_eq!(o[1].satoshis, 1000);
    assert_eq!(o[1].balance, 70);
    assert_eq!(o[1].merge_balance, 0);
}

#[test]
#[should_panic(expected = "amount > 0")]
fn test_transfer_zero_amount_fails() {
    new_token(alice(), 100).transfer(&alice_sig(), bob(), 0, 1000);
}

#[test]
#[should_panic(expected = "amount <= total_balance")]
fn test_transfer_exceeds_balance_fails() {
    new_token(alice(), 100).transfer(&alice_sig(), bob(), 101, 1000);
}

#[test]
fn test_send() {
    let mut c = new_token(alice(), 100);
    c.send(&alice_sig(), bob(), 1000);
    let o = FungibleToken::take_outputs();
    assert_eq!(o.len(), 1);
    assert_eq!(o[0].owner, bob());
    assert_eq!(o[0].balance, 100);
    assert_eq!(o[0].merge_balance, 0);
}

#[test]
#[should_panic(expected = "other_balance >= 0")]
fn test_merge_negative_other_balance_fails() {
    let all_prevouts = vec![0u8; 72];
    new_token(alice(), 100).merge(&alice_sig(), -1, all_prevouts, vec![], 1000);
}

#[test]
#[should_panic(expected = "hash256(&all_prevouts) == extract_hash_prevouts(&self.tx_preimage)")]
fn test_merge_tampered_prevouts_fails() {
    let tampered_prevouts = vec![0xffu8; 72];
    new_token(alice(), 30).merge(&alice_sig(), 70, tampered_prevouts, vec![], 1000);
}

/// Replaces the old `test_merge` / `test_merge_pre_existing_merge_balance`,
/// which asserted output slots of a four-argument merge the shipped contract
/// no longer has. With prevouts the mocks accept (72 zero bytes) the shipped
/// merge passes the prevouts gate, identifies itself as input 0 and stops at
/// the companion-parent binding — the first assert no native input can satisfy
/// (see the file header).
#[test]
#[should_panic(expected = "hash256(&other_parent_tx) == companion_txid")]
fn test_merge_honest_prevouts_reach_companion_binding() {
    let all_prevouts = vec![0u8; 72];
    token(alice(), 20, 10).merge(&alice_sig(), 50, all_prevouts, vec![0u8; 64], 1000);
}

#[test]
fn test_transfer_exact_balance() {
    let mut c = new_token(alice(), 100);
    c.transfer(&alice_sig(), bob(), 100, 1000);
    let o = FungibleToken::take_outputs();
    assert_eq!(o.len(), 1);
    assert_eq!(o[0].balance, 100);
}

#[test]
fn test_transfer_uses_merge_balance() {
    let mut c = token(alice(), 60, 40);
    c.transfer(&alice_sig(), bob(), 80, 1000);
    let o = FungibleToken::take_outputs();
    assert_eq!(o.len(), 2);
    assert_eq!(o[0].balance, 80);
    assert_eq!(o[1].balance, 20);
    assert_eq!(o[0].merge_balance, 0);
    assert_eq!(o[1].merge_balance, 0);
}

#[test]
fn test_send_uses_merge_balance() {
    let mut c = token(alice(), 60, 40);
    c.send(&alice_sig(), bob(), 1000);
    let o = FungibleToken::take_outputs();
    assert_eq!(o.len(), 1);
    assert_eq!(o[0].balance, 100);
    assert_eq!(o[0].merge_balance, 0);
}

#[test]
fn test_compile() {
    runar::compile_check(
        include_str!("FungibleTokenExample.runar.rs"),
        "FungibleTokenExample.runar.rs",
    ).unwrap();
}
